package org.tielang.tink;

import java.nio.charset.StandardCharsets;
import java.util.Arrays;
import java.util.HexFormat;

/**
 * KAT tests for {@link TinkV3} (plain main, no external dependencies).
 *
 * <p>Vectors are generated by the tie reference implementation
 * ({@code tlib/std/tink_v3.tie}) and must match byte-for-byte (same vector
 * set as the C / Python / Rust ports).
 */
public final class TestTinkV3 {

    private static int failures = 0;

    private static void check(boolean cond, String name) {
        if (cond) {
            System.out.println("PASS " + name);
        } else {
            failures++;
            System.out.println("FAIL " + name);
        }
    }

    private static byte[] pat(int n) {
        byte[] b = new byte[n];
        for (int i = 0; i < n; i++) {
            b[i] = (byte) ((i * 7 + 3) & 0xFF);
        }
        return b;
    }

    private static String hex(byte[] b) {
        return HexFormat.of().formatHex(b);
    }

    private static boolean hexEq(byte[] b, int off, int len, String exp) {
        return HexFormat.of().formatHex(b, off, off + len).equals(exp);
    }

    public static void main(String[] args) {
        // ---- CRC32C vectors ----
        check(TinkV3.crc32c("123456789".getBytes(StandardCharsets.UTF_8)) == 0xE3069283L,
                "crc_123456789");
        check(TinkV3.crc32c(pat(9)) == 2452382926L, "crc_pat9");
        check(TinkV3.crc32c(new byte[32]) == 2324772522L, "crc_rfc_zeros");
        byte[] ff = new byte[32];
        Arrays.fill(ff, (byte) 0xFF);
        check(TinkV3.crc32c(ff) == 1655221059L, "crc_rfc_ff");
        byte[] inc = new byte[32];
        for (int i = 0; i < 32; i++) {
            inc[i] = (byte) i;
        }
        check(TinkV3.crc32c(inc) == 1188919630L, "crc_rfc_inc");

        // ---- single frames ----
        byte[] f = TinkV3.msgEncode(pat(13));
        check(hex(f).equals("746b0304000c0000000000000000000d030a11181f262d343b424950571d47ab1e"),
                "single_frame_13");
        byte[] f2 = TinkV3.msgEncode(inc);
        check(hex(f2).equals("746b0304000c00000000000000000020000102030405060708090a0b0c0d0e0f"
                + "101112131415161718191a1b1c1d1e1fee038132"), "single_frame_32inc");
        byte[] f0 = TinkV3.msgEncode(new byte[0]);
        check(hex(f0).equals("746b0304000c00000000000000000000e7ccf215"), "empty_frame");

        // ---- EXT frame ----
        byte[] fe = TinkV3.frameEncodeExt(new byte[] {0x78},
                new byte[] {0x00, 0x02, 0x00, 0x01, 0x05});
        check(hex(fe).equals("746b0304000d000000000000000000010005000200010578479e613c"),
                "ext_frame_kat");
        TinkV3.Decoded dr = TinkV3.msgDecode(fe, 0);
        check(dr != null && dr.payload.length == 1 && dr.payload[0] == 0x78 && dr.next == fe.length,
                "ext_frame_decode");

        // ---- fragmented (70000 -> 2 frames) ----
        byte[] p = pat(70000);
        byte[] fr = TinkV3.msgEncode(p);
        boolean ok = fr.length == 70048;
        ok = ok && hexEq(fr, 0, 16, "746b030400140000000000000000ffff");
        ok = ok && hexEq(fr, 65551, 4, "112dd201");
        ok = ok && hexEq(fr, 65555, 20, "746b0304001c000000000000000111790000fffb");
        ok = ok && hexEq(fr, fr.length - 4, 4, "38fb521f");
        check(ok, "fragmented_layout");
        TinkV3.Decoded fd = TinkV3.msgDecode(fr, 0);
        check(fd != null && Arrays.equals(fd.payload, p) && fd.next == fr.length,
                "fragmented_roundtrip");
        byte[] bad = fr.clone();
        bad[65600] ^= 0x01;
        check(TinkV3.msgDecode(bad, 0) == null, "fragmented_tamper_reject");

        // ---- boundaries ----
        byte[] pm = pat(65535);
        byte[] fm = TinkV3.frameEncode(pm);
        boolean ok2 = fm.length == 65555;
        ok2 = ok2 && hexEq(fm, 0, 16, "746b0304000c0000000000000000ffff");
        ok2 = ok2 && hexEq(fm, fm.length - 4, 4, "4995f11e");
        check(ok2, "max_single_65535");
        check(TinkV3.msgEncode(Arrays.copyOf(pm, 65532)).length == 65532 + 2 * 24,
                "boundary_65532_two_frags");

        // ---- v1 frames are rejected (generational upgrade) ----
        byte[] v1 = new byte[] {0, 0, 0, 3, (byte) 0xAA, (byte) 0xBB, (byte) 0xCC, 0, 0, 0, 0};
        check(TinkV3.msgDecode(v1, 0) == null, "v1_rejected");

        if (failures == 0) {
            System.out.println("ALL:PASS");
            System.exit(0);
        }
        System.out.println("ALL:FAIL (" + failures + ")");
        System.exit(1);
    }
}
